CREATE TABLE public.habits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, name text NOT NULL, icon text NOT NULL DEFAULT '', reminder_time text NOT NULL DEFAULT '', repeat_days integer[] NOT NULL DEFAULT ARRAY[0,1,2,3,4,5,6], start_day date NOT NULL, archived_day date, versions jsonb NOT NULL DEFAULT '[]'::jsonb, UNIQUE(id,user_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.habits TO authenticated; GRANT ALL ON public.habits TO service_role;
ALTER TABLE public.habits ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own habits" ON public.habits FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.habit_completions (habit_id uuid NOT NULL, user_id uuid NOT NULL, day date NOT NULL, PRIMARY KEY(habit_id,day), FOREIGN KEY(habit_id,user_id) REFERENCES public.habits(id,user_id) ON DELETE CASCADE);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.habit_completions TO authenticated; GRANT ALL ON public.habit_completions TO service_role;
ALTER TABLE public.habit_completions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own habit history" ON public.habit_completions FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE FUNCTION public.validate_habit_completion() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE today date; h public.habits; v jsonb; BEGIN SELECT (now() AT TIME ZONE timezone)::date INTO today FROM public.profiles WHERE id=auth.uid(); IF today IS NULL OR NEW.day>today OR NEW.day<today-7 THEN RAISE EXCEPTION 'Only today and the last seven days may be corrected'; END IF; SELECT * INTO h FROM public.habits WHERE id=NEW.habit_id AND user_id=auth.uid(); IF NOT FOUND OR NEW.day<h.start_day OR (h.archived_day IS NOT NULL AND NEW.day>=h.archived_day) THEN RAISE EXCEPTION 'Habit not scheduled'; END IF; SELECT item INTO v FROM jsonb_array_elements(h.versions) item WHERE (item->>'from')::date<=NEW.day ORDER BY (item->>'from')::date DESC LIMIT 1; IF v IS NULL OR NOT (v->'days' @> to_jsonb(extract(dow FROM NEW.day)::integer)) THEN RAISE EXCEPTION 'Habit not scheduled'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_habit_completion BEFORE INSERT OR UPDATE ON public.habit_completions FOR EACH ROW EXECUTE FUNCTION public.validate_habit_completion();